#!/usr/bin/env python3
"""Writes script/ep41.en.json … ep50.en.json from one compact table (the batch's words live here until an episode is
voiced; after that the JSON is the source and this file is only the record of how the batch was drafted).

    python3 -I tools/write_scripts_41_50.py            write all ten
    python3 -I tools/estimate.py --ep 41 --write       then predict the voice lengths
    node tools/gate.mjs --ep 41                        and gate the script
"""
import json, os
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SRC = "BORI Critical Edition"
MADE = "Voices: synthetic · Drawn in code"
SNAKE = "STAGING RULE (snake and man): a two-shot from the waist up on clear ground; the snake two body-widths in front of him, rearing on an S-curve until its head is at his chest height; its head never overlaps his body below the chest, and no caption or plaque crosses either face."

def L(id, text, speaker=None, say=None, **o):
    d = {"id": id}
    if speaker: d["speaker"] = speaker
    d["speed"] = o.pop("speed", 1.0 if speaker else NARR)
    d["text"] = text
    d["say"] = say or text.strip('"')
    d["est"] = 3.0
    d["pre"] = o.pop("pre", 250)
    d["post"] = o.pop("post", 300)
    d.update(o)
    return d

def hook(text, speaker=None, say=None, **o):
    return L("hook", text, speaker, say, pre=60, post=o.pop("post", 1100), speed=o.pop("speed", 1.1), role="hook", caption=False, **o)

def nxt(title):
    return {"id": "next", "text": f"Next: {title}", "voice": False, "est": 1.1, "role": "next", "caption": False, "cam": "push", "note": "The NEXT › band over the cliffhanger image, with the source line; dissolve into frame 1."}

EP = {}
NARR = 1.04   # the narrator's line speed; set per episode before its table (1.0 where the words run close to 2.6 a second)
TITLES = {40: "The Sacrifice Stops", 41: "The Bride and the Demon", 42: "The Child Who Fell", 43: "The Curse on Fire", 44: "Ruru and Pramadvara", 45: "Half a Life", 46: "The Snake Who Was a Sage",
          47: "Vyasa Comes to the Sacrifice", 48: "The Whole Story in One Breath", 49: "The King, the Fish and the Ferry Girl", 50: "Born on an Island", 51: "The Burden of the Earth"}

